package app;
import java.security.GeneralSecurityException;
class Child extends GeneralSecurityException {
 static int calls;Throwable overrideCause;
 Child(String message,Throwable other){super(message);overrideCause=other;}
 @Override public Throwable getCause(){calls++;return overrideCause;}
 Throwable body(){return super.getCause();}
 Throwable[] suppressed(){return super.getSuppressed();}
 <GeneralSecurityException> boolean seed(Throwable cause){return super.initCause(cause)==this;}
}
public class Main {
 public static void main(String[] args){String text=new String(new char[]{'r',0,(char)0xd800});Throwable cause=new Exception("cause");Throwable other=new Exception("other");Child value=new Child(text,other);
 System.out.println(value.seed(cause)+":"+(value.body()==cause)+":"+Child.calls+":"+(value.getCause()==other)+":"+Child.calls);
 value.addSuppressed(other);Throwable[] suppressed=value.suppressed();System.out.println((suppressed[0]==other)+":"+suppressed.length+":"+(value.getMessage()==text)+":"+value.getMessage().length()+":"+(int)value.getMessage().charAt(2));
 }
}

