package app;
class Parent extends java.security.GeneralSecurityException {
 static String trace="";Throwable selected;String text;
 Parent(Throwable value,String detail){super("base");selected=value;text=detail;}
 @Override public Throwable getCause(){trace+="parent-cause,";return selected;}
 @Override public String getMessage(){trace+="message,";return text;}
 @Override public String toString(){trace+="text,";return text;}
 @Override public void printStackTrace(){trace+="parent-print,";}
}
class Child extends Parent {
 Child(Throwable value,String detail){super(value,detail);}
 @Override public Throwable getCause(){trace+="child-cause,";return null;}
 @Override public void printStackTrace(){trace+="child-print,";}
 Throwable body(){return super.getCause();}
 void printBody(){super.printStackTrace();}
}
public class Main {
 public static void main(String[] args){Throwable cause=new Exception("cause");String text=new String(new char[]{'r',0,(char)0xd800});Child child=new Child(cause,text);java.security.GeneralSecurityException view=child;
 System.out.println((child.body()==cause)+":"+(child.getCause()==null));child.printBody();child.printStackTrace();System.out.println(Parent.trace);
 Parent.trace="";System.out.println((view.getMessage()==text)+":"+(view.toString()==text)+":"+(child.getClass().getSuperclass()==Parent.class)+":"+(view.getClass()==Child.class));System.out.println(Parent.trace);
 }
}

package app;
import observe.URISyntaxException;
import observe.Child;
public class Main {
  public static void main(String[] args) {
    URISyntaxException source = new URISyntaxException();
    Child child = new Child();
    URISyntaxException base = child;
    foreign.URISyntaxException other = new foreign.URISyntaxException();
    System.out.println(source.getCause() + ":" + source.getSuppressed());
    System.out.println(source.initCause("ab") == source);
    source.printStackTrace();
    System.out.println(source.getCause() + ":" + source.getSuppressed());
    System.out.println(base.getCause() + ":" + base.getSuppressed());
    System.out.println(base.initCause("x") == child);
    base.printStackTrace();
    System.out.println(child.getCause() + ":" + child.getSuppressed());
    System.out.println(other.initCause("abc") == other);
    other.printStackTrace();
    System.out.println(other.getCause() + ":" + other.getSuppressed());
    System.out.println(source.getClass().getName() + ":" + child.getClass().getName() + ":" + other.getClass().getName());
    System.out.println(child.getClass().getSuperclass().getName());
    System.out.println(URISyntaxException.class.isInstance(child) + ":" + Throwable.class.isInstance(source) + ":" + Throwable.class.isInstance(child) + ":" + Throwable.class.isInstance(other));
  }
}

